import {
  pgTable,
  uuid,
  timestamp,
  varchar,
  decimal,
  jsonb,
  uniqueIndex,
  index,
} from 'drizzle-orm/pg-core';
import type { InferInsertModel, InferSelectModel } from 'drizzle-orm';
import { PaymentIntentModel } from './paymentIntent.model';

/**
 * Payment Transaction Model
 *
 * Stores individual checkout attempts generated by a Payment Intent.
 * Supports multiple attempts (e.g. Attempt 1: Failed, Attempt 2: Paid) for a single booking intent.
 */
export const PaymentTransactionModel = pgTable(
  'payment_transactions',
  {
    id: uuid('id').primaryKey().defaultRandom(),
    paymentIntentId: uuid('payment_intent_id')
      .references(() => PaymentIntentModel.id, { onDelete: 'cascade' })
      .notNull(),

    // Payment Instrument Parameters
    paymentMode: varchar('payment_mode', { length: 50 }).notNull(), // 'ONLINE' | 'OFFLINE'
    paymentMethod: varchar('payment_method', { length: 50 }).notNull(), // 'UPI' | 'CARD' | 'NETBANKING' | 'WALLET' | 'CASH' | 'CHEQUE'
    paymentProvider: varchar('payment_provider', { length: 50 }), // 'razorpay' | 'cashfree' | 'stripe' | null

    paymentStatus: varchar('payment_status', { length: 50 })
      .default('Pending')
      .notNull(), // 'Paid', 'Pending', 'Failed', 'Expired'
    price: decimal('price', { precision: 12, scale: 2 }).notNull(),

    // Gateway metadata
    gatewayOrderId: varchar('gateway_order_id', { length: 255 }).notNull(),
    transactionId: varchar('transaction_id', { length: 255 }), // Session ID or gateway reference
    gatewayResponse: jsonb('gateway_response'),

    // Dynamic Split breakdowns written upon successful capture
    platformCommission: decimal('platform_commission', {
      precision: 12,
      scale: 2,
    }),
    pgFee: decimal('pg_fee', { precision: 12, scale: 2 }),
    gstAmount: decimal('gst_amount', { precision: 12, scale: 2 }),
    convenienceFee: decimal('convenience_fee', { precision: 12, scale: 2 }),
    transferredAmount: decimal('transferred_amount', {
      precision: 12,
      scale: 2,
    }), // 0.00 for Direct Platform Subscriptions

    refundedAmount: decimal('refunded_amount', { precision: 12, scale: 2 }),
    refundNotes: varchar('refund_notes', { length: 500 }),

    createdAt: timestamp('created_at').defaultNow().notNull(),
    updatedAt: timestamp('updated_at').defaultNow(),
  },
  (table) => [
    uniqueIndex('gateway_order_unique').on(
      table.paymentProvider,
      table.gatewayOrderId
    ),
    index('payment_tx_intent_idx').on(table.paymentIntentId),
    index('payment_tx_status_idx').on(table.paymentStatus),
  ]
);

export type PaymentTransaction = InferSelectModel<
  typeof PaymentTransactionModel
>;
export type NewPaymentTransaction = InferInsertModel<
  typeof PaymentTransactionModel
>;
